interface Circle { kind: "circle"; r: number }
interface Square { kind: "square"; side: number }
type Shape = Circle | Square;

function describe(s: Shape): string {
  if (s.kind === "circle") return `circle:${typeof s.r}`;
  return `square:${typeof s.side}`;
}

console.log(describe({ kind: "circle", r: 2 }));
console.log(describe({ kind: "square", side: 3 }));
console.log(typeof describe);
```

下面的类型守卫编译通过，但在运行时会把 `{ r: 1 }` 判成 `Circle`，导致 `area` 返回 `NaN`。指出问题并改正。

```ts
function isCircle(x: unknown): x is Circle {
  return typeof x === "object" && x !== null;
}

function area(s: unknown): number {
  if (isCircle(s)) return Math.PI * s.r ** 2;
  throw new Error("not a circle");
}
```

