function isCircle(x: unknown): x is Circle {
  return (
    typeof x === "object" && x !== null &&
    (x as { kind?: unknown }).kind === "circle" &&
    typeof (x as { r?: unknown }).r === "number"
  );
}

function groupBy<T, K extends string>(items: T[], keyOf: (item: T) => K): Partial<Record<K, T[]>> {
  const out: Partial<Record<K, T[]>> = {};
  for (const it of items) {
    const k = keyOf(it);
    (out[k] ??= []).push(it);
  }
  return out;
}

const people = [{ name: "a", dept: "eng" }, { name: "b", dept: "design" }, { name: "c", dept: "eng" }];
console.log(JSON.stringify(groupBy(people, (p) => p.dept as "eng" | "design")));

type Circle = { kind: "circle"; r: number };
type Square = { kind: "square"; side: number };
type Triangle = { kind: "triangle"; a: number; b: number; c: number };
type Shape = Circle | Square | Triangle;

function area(s: Shape): number {
  switch (s.kind) {
    case "circle": return Math.PI * s.r ** 2;
    case "square": return s.side ** 2;
    case "triangle": {
      const p = (s.a + s.b + s.c) / 2;
      return Math.sqrt(p * (p - s.a) * (p - s.b) * (p - s.c));
    }
    default: {
      const never_: never = s;
      throw new Error(`未处理的形状: ${JSON.stringify(never_)}`);
    }
  }
}

console.log(area({ kind: "square", side: 3 }).toFixed(2)); // 9.00
console.log(area({ kind: "triangle", a: 3, b: 4, c: 5 }).toFixed(2)); // 6.00

